  rows.push([],['未指定組別的預設原板',stockLabel(r.input)],['筒身板向',shellLayoutLabel(r.input)],['縱縫配置',r.shellLayoutState?.custom?'逐圈起點角／逐片弧長':r.input.seamLayout==='stagger'?'錯開半片節距（未作縫距規範校核）':'對齊（接縫交會尚待設計確認）'],['已排毛坯 kg',r.allocatedBlankWeight],['餘料及切割損耗 kg',r.offcutWeight],['毛坯利用 %',r.utilization],[],['筒身板片','由底第幾圈','圈內第幾片','底部高程 mm','本圈起縫角 deg','板片起點角 deg','成品圓周長 mm','成品高 mm','來源原板','原板左起 mm','原板上起 mm','毛坯弧向 mm','毛坯軸向 mm']);
  for(const piece of r.assembly)rows.push([piece.id,piece.course,piece.panel,piece.z,piece.angle,piece.start/r.circumference*360,piece.length,piece.height,piece.sheet??'未排入',piece.x??'',piece.y??'',shellPiecePart(r,piece.id).width,shellPiecePart(r,piece.id).height]);
  rows.push([],['其他板型比較（同板向）','採購狀態','已排原板張數','原板估重 kg','餘料及損耗 kg','筒身縱縫','筒身環縫','筒身焊縫長 mm']);
  for(const option of compareTankStocks(r.input)){const c=option.result;rows.push([option.label,c.valid&&c.shellLayoutState?.valid!==false?(c.stockComplete?'已排入':'不完整，尚有板件尺寸／材料待補'):(c.shellLayoutState?.issues?.[0]?.message??c.issues[0].message),c.plateSheets??'',c.stockWeight??'',c.offcutWeight??'',c.verticalSeams??'',c.horizontalSeams??'',c.weldLength??'']);}
  for(const issue of r.materialIssues)rows.push(['待解決',issue.message]);if(r.input.referenceCase===V1102_ID)rows.push([],['V-1102 圖面重建草稿；未完成製造詳圖'],...V1102_NOTES);
  if(r.nozzlePlan?.items.length){rows.push([],['管嘴編號','用途','安裝面','高度 mm','偏心 mm','方位 deg','外徑 mm','管厚 mm','外壁到端面 mm','內凸 mm','最短管長 mm','最長管長 mm','先備管長 mm','端部接法','法蘭外徑 mm','法蘭占長 mm','法蘭單重 kg','法蘭規格','中心板片']);for(const n of r.nozzlePlan.items){if(n.detailedAssembly)rows.push([n.mark||n.id,'管料／法蘭由分件明細取代',n.detailedAssembly,'以下尺寸為端口定位參考，原概算不加計']);rows.push([n.mark||n.id,n.name,NOZZLE_HOSTS[n.host],n.host==='shell'?n.height:'',n.host==='shell'?'':n.radius,n.angle,n.od,n.thickness,n.projection,n.inside,n.minCutLength,n.maxCutLength,n.blankLength,NOZZLE_ENDS[n.end],n.end==='bare'?'':n.flangeOD,n.end==='bare'?'':n.flangeLength,n.end==='bare'?'':n.flangeWeight||'未提供',flangeDescription(n),n.shellPiece??'']);rows.push([n.mark||n.id,'管軸配置',n.axisMode,n.offset,'接件構成',n.construction,n.cutReady?'可估管長':'不拆算直管下料，接件與內管重量未計']);if(n.end!=='bare')rows.push([n.id+' 法蘭規格記錄',n.flangeSize,n.flangeClass,n.flangeFacing,n.flangeMaterial,n.flangeSpec,flangeProvenance(n)]);if(n.end==='so')rows.push([n.id+' SO 管端退縮 mm',n.soSetback]);rows.push([n.id+' 孔口與留料',n.hole,n.holeGap,n.allowance,n.construction==='integral'?'依接件詳圖':n.end==='wn'?n.weldGap:0]);rows.push([n.id+' 補強／載荷記錄',n.reinforcement||'待確認']);for(const warning of n.warnings)rows.push([n.id+' 待確認',warning]);}rows.push(['未被明細取代的管嘴及法蘭估重 kg',r.nozzlePlan.accountedWeight??r.nozzlePlan.extraWeight],['法蘭單重未提供只數',r.nozzlePlan.unknownFlangeWeight]);for(const note of r.nozzlePlan.notes)rows.push(['管嘴估算假設',note]);}
